type ImportTracker string

// ImportedOperation defines model for ImportedOperation.
type ImportedOperation struct {
	// AmountMinor Signed as the journal records the type: negative for buy, withdrawal, fee and tax
	AmountMinor int64 `json:"amount_minor"`

	// CategoryId The family's category the row will be filed under: named by the table, or found by the family's rules (an everyday account only); null when neither
	CategoryId   nullable.Nullable[openapi_types.UUID] `json:"category_id"`
	Counterparty string                                `json:"counterparty"`
	Currency     string                                `json:"currency"`
	FeeMinor     int64                                 `json:"fee_minor"`
	InstrumentId nullable.Nullable[openapi_types.UUID] `json:"instrument_id,omitempty"`
	Note         string                                `json:"note"`

	// OccurredOn Date YYYY-MM-DD
	OccurredOn string                    `json:"occurred_on"`
	Price      nullable.Nullable[string] `json:"price,omitempty"`
	Quantity   nullable.Nullable[string] `json:"quantity,omitempty"`

	// Type What the entry is. `redemption`: a bond reaching maturity (or a fund's units redeemed, decision Р-13) — computed as a sale, named apart. `exchange_out`/`exchange_in`: the two legs of a securities conversion on one account and day (a receipt into its share, a fund reissued): the parcel travels whole with its purchase days, nothing is realized, and amount_minor is the cost basis that moved, not money. `spinoff_out`/`spinoff_in`: a spin-off — the original keeps every unit (so `spinoff_out` has no quantity) and the new paper arrives with the event's `basis_share` of the cost (0 by default) and the original purchase days. The last four are written only by the corporate-actions registry (`source: registry`) and are never created or deleted through this API.
	Type OperationType `json:"type"`
}

// InBaseGap Which term stopped Position.in_base; the terms are checked in this order and the first failure is published. `undated_lot`: a lot still held has no acquisition date — permanent. `no_rate_lot_date`: no rate for a lot's date or earlier. `no_rate_income_date`: the same for an income payment's date. `no_rate_today`: no rate today or earlier for the currency the valuation is denominated in, asked only when there is a valuation. The `no_rate_*` gaps close by themselves once the rates are loaded.
type InBaseGap string

// Instrument defines model for Instrument.
type Instrument struct {
	// CoingeckoId A cryptocurrency's coin at CoinGecko, which prices it daily (decision Р-20): the price job picks the largest coin with the paper's ticker, since tickers are not unique among coins, and a person may correct it. Empty for anything else and until a coin is picked; absent from older answers.
	CoingeckoId *string `json:"coingecko_id,omitempty"`
	Currency    string  `json:"currency"`

	// FaceCurrency The currency face_value_minor is denominated in, which need not be the instrument's own. Null exactly when face_value_minor is null; never empty (a CHECK constraint). Its ISO-4217 shape is enforced by every writer but not by the database, so no pattern is promised for stored rows.
	FaceCurrency nullable.Nullable[string] `json:"face_currency,omitempty"`

	// FaceValueMinor What one bond is worth at redemption, in face_currency's minor units. Null for a bond without a recorded face value and for any other type (rows written before that rule are returned as they stand; PATCH clears them). Always positive and never without face_currency — a CHECK constraint backs both for every stored row. No maximum is stated: the write's cap has no constraint behind it.
	FaceValueMinor nullable.Nullable[int64] `json:"face_value_minor,omitempty"`
	Figi           string                   `json:"figi"`
	Frozen         bool                     `json:"frozen"`
	Id             openapi_types.UUID       `json:"id"`
	Isin           string                   `json:"isin"`
	Name           string                   `json:"name"`
	Ticker         string                   `json:"ticker"`
	Type           InstrumentType           `json:"type"`
}

